import{z as s,x as n,o as B,c as C,q as t,j as r,D as A,d as l,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"网格世界实验课","description":"","frontmatter":{"title":"网格世界实验课","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/gridworld-lab-lesson.md","filePath":"llm/gridworld-lab-lesson.md","lastUpdated":1791063341000}'),d={name:"llm/gridworld-lab-lesson.md"};function m(D,E,p,S,f,u){const e=n("Mermaid");return B(),C("div",null,[E[2]||(E[2]=t('<h1 id="网格世界实验课" tabindex="-1">网格世界实验课 <a class="header-anchor" href="#网格世界实验课" aria-label="Permalink to &quot;网格世界实验课&quot;">​</a></h1><div class="epigraph"><p>读十遍收敛定理，不如亲眼看一条振荡的曲线；网格世界小到每格可查，大到足以复现本单元的全部病症。</p><footer>—— 据 Sutton &amp; Barto, 2018, 第 5–6 章例题（Gridworld、Cliff Walking）整理</footer></div><p><a href="/llm/deadly-triad">上一课</a>指出函数逼近、自举与离策略合取时保证消失；理论给的是「会发生什么」，实验课回答「在哪、何时、看见什么」。本课把本单元的蒙特卡洛、TD(0)、SARSA 与 Q 学习装进同一个 tabular 网格世界，给出伪代码级实现要点与一份可复现实验清单，这也是「预测与控制」课序的收束：评估由 MC/TD 完成，改进由 ε-贪婪完成。但值方法的改进始终要扫动作、要值表——动作换成几万词表的 token 就扫不动；绕开值表、直接对策略参数求导的路线，是下一单元「策略梯度」的起点。本课之后默认你跑过这套实验。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前四课的断言都是可观察现象：MC 无偏但慢、TD 偏差换方差、max 过估计、步长敏感、探索决定访问。断言要对照才能立住，对照要同一环境。网格世界的好处：状态可枚举、真值可以先算——用<a href="/llm/value-policy-iteration">值迭代</a>离线解出 \\(V^*\\) 当标尺，每个格子的误差逐格可查；这在小世界之外做不到。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>环境口径：\\(5\\times5\\) 或 \\(10\\times10\\) 网格，4 个动作；终止格 +1，陷阱 −1，每步 −0.04；转移以 0.8 概率走目标方向、各 0.1 滑向两侧——确定性转移会让 TD 目标只剩初值误差，太干净，噪声必须保留；\\(\\gamma=0.9\\)；全部进 config。算法侧四选一插桩：MC 在回合末按访问记账；TD(0) 每步 \\(V(s_t)\\leftarrow V(s_t)+\\alpha\\delta_t\\)；SARSA 的 \\(\\delta_t\\) 用实际采出的 \\(a_{t+1}\\)；Q 学习的 \\(\\delta_t\\) 用 \\(\\max_{a&#39;}Q\\)。探索用带保底的 \\(\\varepsilon\\) 衰减：\\(\\varepsilon_n=\\max(0.05,\\,1/n(s,a))\\)（严格的 GLIE 要求 \\(\\varepsilon\\to0\\)，这里刻意留 5% 保底）。评估协议：冻结策略、关掉探索跑 rollout，或直接逐格算 \\(\\mathrm{RMSE}(V,V^*)\\)。</p><p><span class="marginnote">术语翻译：带保底的 ε 衰减就是「访问得越多，探索率越低」的口径——比严格的 GLIE 宽松——某对状态-动作没去过就多试，去多了就少试，并留 5% 保底防止彻底停止探索。目的只有一个：训练后期既探索得够，又能收敛到一条确定策略。</span></p>',8)),(B(),r(o,null,{default:A(()=>[i(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22config%EF%BC%9A%E7%BD%91%E6%A0%BC%E3%80%81%E5%99%AA%E5%A3%B0%E3%80%81%CE%B3%E3%80%81%CE%B1%E3%80%81%CE%B5%E3%80%81%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20ENV%5B%22%E7%8E%AF%E5%A2%83%EF%BC%9A%E6%BB%91%E5%8A%A8%E8%BD%AC%E7%A7%BB%20%2B%20%E5%A5%96%E5%8A%B1%20%2B%20%E7%BB%88%E6%AD%A2%22%5D%0A%20%20CFG%20--%3E%20REF%5B%22%E5%80%BC%E8%BF%AD%E4%BB%A3%E7%A6%BB%E7%BA%BF%E8%A7%A3%E5%87%BA%20V*%20%E5%BD%93%E6%A0%87%E5%B0%BA%22%5D%0A%20%20ENV%20--%3E%20LOOP%5B%22%E8%AE%AD%E7%BB%83%E5%BE%AA%E7%8E%AF%EF%BC%9A%E9%87%87%E6%A0%B7%20%E2%86%92%20%E6%8C%89%E7%AE%97%E6%B3%95%E6%9B%B4%E6%96%B0%22%5D%0A%20%20LOOP%20--%3E%20ALG%7B%22%E7%AE%97%E6%B3%95%E6%8F%92%E6%A1%A9%22%7D%0A%20%20ALG%20--%3E%7CMC%7C%20A1%5B%22%E5%9B%9E%E5%90%88%E6%9C%AB%E6%8C%89%E8%AE%BF%E9%97%AE%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20ALG%20--%3E%7C%22TD(0)%22%7C%20A2%5B%22%E6%AF%8F%E6%AD%A5%20V%20%2B%3D%20%CE%B1%CE%B4%22%5D%0A%20%20ALG%20--%3E%7CSARSA%7C%20A3%5B%22%CE%B4%20%E7%94%A8%E5%AE%9E%E9%99%85%20a%E2%80%B2%22%5D%0A%20%20ALG%20--%3E%7CQ%20%E5%AD%A6%E4%B9%A0%7C%20A4%5B%22%CE%B4%20%E7%94%A8%20max%20Q(s%E2%80%B2%2C%20%C2%B7)%22%5D%0A%20%20A1%20--%3E%20EVAL%5B%22%E5%86%BB%E7%BB%93%E7%AD%96%E7%95%A5%EF%BC%9ARMSE%20%E5%AF%B9%20V*%22%5D%0A%20%20A2%20--%3E%20EVAL%0A%20%20A3%20--%3E%20EVAL%0A%20%20A4%20--%3E%20EVAL%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"横轴一律用环境步数而不是回合数：MC 的回合更长，按回合数画会显得学得快。0.8/0.1/0.1 的滑动噪声加 \\(\\gamma=0.9\\)，有效视界约 \\(1/(1-\\gamma)=10\\) 步；噪声与视界一起写进 config。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"应该看到的现象，对应前四课的断言。其一，MC 曲线抖、起步慢、长时间贴标尺；TD 先陡后平、落点被初值与步长拖拽——偏差换方差有了肉眼形状。其二，α 热图上两族算法的容忍带不同；奖励尺度一改，最优 α 跟着移。其三，给奖励加噪声后，Q 学习的高估随 σ 与 α 增大——max 挑误差；Double Q 对照把高估压回去。其四，悬崖口径（每步 −1、坠崖 −100 回起点）下，Q 学习学出贴崖最短路而执行期回报差，SARSA 学安全路——同策略如实记探索代价。其五，ε=0 时误差停在没访问过的格子：访问直方图要和误差图并排看。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：SARSA 是谨慎的登山者，把「我可能手滑」记进价值，宁可绕远路；Q 学习是纸上谈兵的最优者，假设每步都完美执行，于是把悬崖边的最短路当成最好——可真滑一步就掉下去。同一环境、不同更新目标，走出两种性格。")],-1)),(B(),r(o,null,{default:A(()=>[i(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%82%AC%E5%B4%96%E5%8F%A3%E5%BE%84%E8%AE%AD%E7%BB%83%22%5D%20--%3E%20D%7B%22%E6%9B%B4%E6%96%B0%E7%9B%AE%E6%A0%87%E7%94%A8%E8%B0%81%3F%22%7D%0A%20%20D%20--%3E%7C%22SARSA%EF%BC%9A%E7%94%A8%E5%AE%9E%E9%99%85%E9%87%87%E5%88%B0%E7%9A%84%20a%E2%80%B2%22%7C%20S%5B%22%E5%90%8C%E7%AD%96%E7%95%A5%EF%BC%9A%E5%A6%82%E5%AE%9E%E8%AE%B0%E5%85%A5%E6%8E%A2%E7%B4%A2%E9%A3%8E%E9%99%A9%22%5D%0A%20%20S%20--%3E%20P1%5B%22%E5%AD%A6%E5%87%BA%E8%BF%9C%E7%A6%BB%E6%82%AC%E5%B4%96%E7%9A%84%E5%AE%89%E5%85%A8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20D%20--%3E%7C%22Q%20%E5%AD%A6%E4%B9%A0%EF%BC%9A%E7%94%A8%20max%20Q(s%E2%80%B2%2C%20%C2%B7)%22%7C%20Q2%5B%22%E7%A6%BB%E7%AD%96%E7%95%A5%EF%BC%9A%E5%81%87%E8%AE%BE%E6%80%BB%E8%B5%B0%E6%9C%80%E4%BC%98%22%5D%0A%20%20Q2%20--%3E%20P2%5B%22%E5%AD%A6%E5%87%BA%E8%B4%B4%E5%B4%96%E6%9C%80%E7%9F%AD%E8%B7%AF%EF%BC%8C%E6%89%A7%E8%A1%8C%E6%9C%9F%E6%98%93%E5%9D%A0%E5%B4%96%22%5D%0A%20%20P1%20--%3E%20CMP%5B%22%E6%89%A7%E8%A1%8C%E6%9C%9F%E5%9D%87%E5%9B%9E%E6%8A%A5%EF%BC%9ASARSA%20%E5%BE%80%E5%BE%80%E6%9B%B4%E9%AB%98%22%5D%0A%20%20P2%20--%3E%20CMP%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p>实验清单（复现口径）：E1 MC 对 TD(0)，同种子集，RMSE 对环境步数；E2 α 扫描 \\(\\alpha\\in\\{0.05,0.1,0.2,0.4,0.8\\}\\)，两算法各一条热图；E3 SARSA 对 Q 学习，悬崖口径，交学习曲线、路径图与执行期均回报；E4 奖励噪声 \\(\\sigma\\in\\{0,0.5,1,2\\}\\) 下 Q 学习对 Double Q，报 \\(\\max_a Q\\) 的系统性高估；E5 探索消融，ε-贪婪对乐观初始化对 ε=0，交访问直方图与 RMSE。底线：每组不少于 50 个种子，报均值与标准差；环境、算法、超参、种子同仓同 config。</p><p><span class="marginnote">数字实例：\\(5\\times5\\) 网格共 25 格、每格 4 个动作，值表只有 100 个数，一台笔记本几秒就能扫完。换成词表 5 万、上下文 1024 的语言任务，「状态」是天文数字级的 token 序列——这就是为什么表格法只能当教学标尺，进不了真实 LLM。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>网格世界太小：表格可行，三要素里缺「函数逼近」，发散在这里不可见——tabular 的安心带不进深度值头。\\(5\\times5\\) 上调出的最优 α 不外推，实验课练的是「看什么、与谁对照」。确定性网格会低估 TD 与 MC 的差距，噪声不可删。改进端的边界最要紧：ε-贪婪在 4 个动作上够用，在词表尺度不可行，值方法的「评估-改进」循环在这里到达适用边界——改进能不能不扫动作、直接对策略本身求导，是下一单元要回答的问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一个环境、四算法、一套值迭代标尺：本单元全部断言逐格可查。</li><li>伪代码要点：环境带滑动噪声、带保底的 ε 衰减、RMSE 对真值、横轴用环境步数。</li><li>五组实验分别钉住：MC/TD 形状差、α 敏感性、max 过估计、同/离策略的探索代价、探索消融。</li><li>表格里看不到致命三要素的发散——缺函数逼近；安心要带条件。</li><li>ε-贪婪扫动作的改进在词表尺度失效，绕开值表对策略求导是下一单元的路线。</li><li>出处：Sutton &amp; Barto 2018 第 5–6 章例题口径（Gridworld、Cliff Walking）；实验协议据本课程整理。</li></ul>',6))])}const h=s(d,[["render",m]]);export{F as __pageData,h as default};
